/**
 * Known-answer vectors for `encodeQr`, so the encoder cannot drift without a
 * test noticing.
 *
 * Each matrix is what this encoder produced when the vector was pinned, after
 * checking it against two independent implementations:
 *
 *   1. It decodes, back to exactly the input text, with jsQR — a separate
 *      decoder — scanning a rendering with a four-module quiet zone.
 *   2. It is module-for-module identical to python-qrcode's output for the
 *      same bytes, at error-correction level M, in byte mode, with the mask
 *      this encoder chose. (Data codewords, Reed-Solomon, interleaving,
 *      function patterns, alignment patterns and version information all
 *      agree; the one thing that differs between libraries is which mask
 *      each prefers, since the specification's penalty rules leave room.)
 *
 * The consequence for anyone editing `src/qr.ts`: a failure here means the
 * output changed, not necessarily that it broke. If a change is intended —
 * a different mask tie-break, say — re-verify by decoding the new matrices
 * with a scanner you trust, and only then update them. Do not update them
 * merely because they differ.
 *
 * `#` is a dark module and `.` a light one; rows are top to bottom, without
 * the quiet zone.
 */

export type QrVector = {
  name: string;
  text: string;
  version: number;
  rows: readonly string[];
};

